  "加入群組": { "zh-TW": "加入群組", en: "Join group", ja: "グループに参加する", ko: "그룹에 가입", vi: "Tham gia nhóm", th: "เข้าร่วมกลุ่ม" },
  "編輯註記群組": { "zh-TW": "編輯註記群組", en: "Edit annotation group", ja: "注釈グループの編集", ko: "주석 그룹 수정", vi: "Chỉnh sửa nhóm chú thích", th: "แก้ไขกลุ่มคำอธิบายประกอบ" },
