export type MerchantMessageKey = keyof typeof merchantMessageRows;

const effectiveMerchantMessageRows: Record<MerchantMessageKey, MerchantMessageRow> = {
  ...merchantMessageRows,
  ...merchantDescriptionOverrides,
};

const merchantMessageCatalog = createMessageCatalog(
  dictionaryFor("zh-TW"),
  {
    en: dictionaryFor("en"),
    ja: dictionaryFor("ja"),
    ko: dictionaryFor("ko"),
    vi: dictionaryFor("vi"),
    th: dictionaryFor("th"),
  },
);

export const merchantMessages = merchantMessageCatalog.messages;

export function getMerchantMessages(locale: AppLocale) {
  return dictionaryFor(locale);
}

export function getMerchantMessage(
  locale: AppLocale,
  key: MerchantMessageKey,
  values: MessageValues = {},
) {
  return merchantMessageCatalog.get(locale, key, values);
}

export function translateMerchantLabel(locale: AppLocale, label: string) {
  return Object.prototype.hasOwnProperty.call(merchantMessages[locale], label)
    ? merchantMessages[locale][label as MerchantMessageKey]
    : label;
}

function dictionaryFor(locale: AppLocale): Record<MerchantMessageKey, string> {
  return Object.fromEntries(
    Object.entries(effectiveMerchantMessageRows).map(([key, row]) => [key, row[locale]]),
  ) as Record<MerchantMessageKey, string>;
}
